Definition has := CC.has_cell.
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      (CH2.blocks_eqb (nth i G.BLS []) BLK0 && CHA.foot_chk GT.NF G.HDECL c BLK0 [] && CBA.regions_eqb (CC.cp_F c) CPF && Nat.leb 35 (CC.cp_nx c) &&
      match CH2.ret_of G.RETS i k with
      | Some j =>
          match nth_error G.CPS j with
          | Some cj =>
              (CH2.blocks_eqb (nth j G.BLS []) BLK0 &&
              if Z.eqb pc PC_ASH then
                (Z.eqb (SR.ps_pc ps) PC_ASH && Nat.eqb i 0 && (Nat.eqb j 1 || Nat.eqb j 2)
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 4128 0 BLK0 [] WREGS_ASH STAT None c ps cj BLK0 [] BLK0 [] with Some ci => Z.eqb (CH2.ci_csp ci) (-48) | None => false end
                 && CL.ps_reg_is ps 10 oE && (CL.ps_reg_is ps 11 lenE || (CL.ps_reg_is ps 11 (ELit 0) && has cells (KRange lenE 0 0)))   (* [comment removed for export] *)
                 && has cells (KWord (SA PE 248) 8 sbE) && has cells (KWord (SA PE 256) 8 sbE) && has cells (KWord (SA PE 264) 8 (ADDE sbE capE)))%bool
              else if Z.eqb pc PC_VPUSH then
                (Z.eqb (SR.ps_pc ps) PC_VPUSH && ((Nat.eqb i 1 && Nat.eqb j 3) || (Nat.eqb i 2 && Nat.eqb j 4))
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 8240 0 [] [] WREGS_VP NEWS_VP None c ps cj BLK0 [] BLK0 [] with Some ci => Z.eqb (CH2.ci_csp ci) (-48) | None => false end
                 && CL.ps_reg_is ps 10 oE && CL.ps_reg_is ps 11 xaE
                 && has cells (KWord (SA (EVar 2) (-33)) 1 (ELit 0)) && has cells (KWord (SA PE 248) 8 sbE) && has cells (KWord (SA PE 256) 8 sbE) && has cells (KWord (SA PE 264) 8 (ADDE sbE capE)))%bool
              else false)%bool
          | None => false
          end
      | None =>
          (Z.eqb pc RETPC && (Nat.eqb i 3 || Nat.eqb i 4) && CBA.exit_base_chk GT.NF RETPC c ps
           && has cells (KWord (SA PE 144) 4 (ELit 0)) && has cells (KWord (SA PE 208) 1 (ELit 1)) && has cells (KWord (SA PE 211) 1 (ELit 1)) && has cells (KWord (SA PE 212) 1 (ELit 0))
           && has cells V0 && has cells V8 && has cells V16)%bool
      end)%bool
  end.
